import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_crashlytics/firebase_crashlytics.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'config.dart';
// Generated by `flutterfire configure` — see README.
import 'firebase_options.dart';
import 'l10n/l10n.dart';
import 'providers/providers.dart';
import 'ui/pages/role_gate.dart';
import 'ui/theme.dart';
import 'ui/widgets/splash_intro.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // Crashes on customers' phones show up in Firebase console → Crashlytics.
  // Only release builds report, so debugging doesn't fill it with noise.
  final crashlytics = FirebaseCrashlytics.instance;
  await crashlytics.setCrashlyticsCollectionEnabled(kReleaseMode);
  FlutterError.onError = crashlytics.recordFlutterFatalError;
  PlatformDispatcher.instance.onError = (error, stack) {
    crashlytics.recordError(error, stack, fatal: true);
    return true;
  };

  // The language picked in the app, if any, so the first frame is already
  // in it.
  final prefs = await SharedPreferences.getInstance();
  runApp(ProviderScope(
    overrides: [
      savedLanguageProvider.overrideWithValue(prefs.getString(languageKey)),
    ],
    child: const ShopLiteApp(),
  ));
}

class ShopLiteApp extends ConsumerWidget {
  const ShopLiteApp({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return MaterialApp(
      title: appName,
      debugShowCheckedModeBanner: false,
      theme: buildAppTheme(),
      // The language picked on the Account tab, else the phone's language
      // when the app has it (lib/l10n), else English.
      locale: ref.watch(localeProvider),
      localizationsDelegates: AppLocalizations.localizationsDelegates,
      supportedLocales: AppLocalizations.supportedLocales,
      // Browsing is open to everyone; sign-in lives on the Account tab, and
      // checkout asks for it on the spot (see ensureSignedIn). Signed-in
      // shop admins and the super admin get their own screens instead.
      home: const SplashIntro(child: RoleGate()),
    );
  }
}
